#!/usr/bin/env bash
# Generated by testing/render-graders.sh from validate.sh. Do not edit by hand.
# Grades the outcome node-in-service and prints one PASS: or FAIL: line.
# Runs on the lab VM as the astrona account (astrona pipes it into bash).

# >>> shared checks >>>
LAB_NAME=ats-032-lab-040-03-02
LAB_CONTEXT="kubernetes-admin@astro-$LAB_NAME"
NODE=controlplane
NAMESPACE=starfleet-032-040-03-02
OUTCOMES="runtime-restarted probe-pods-replaced node-in-service"

kube() {
  sudo -n kubectl --kubeconfig /etc/kubernetes/admin.conf --request-timeout=15s "$@" </dev/null
}

# The bootstrap records the containerd invocation ID and the probe Pod UIDs
# in the ConfigMap maintenance-baseline.
baseline() {
  kube -n "$NAMESPACE" get configmap maintenance-baseline -o jsonpath="{.data.$1}" 2>/dev/null
}

# Context guard: the graders only read this VM's own cluster.
lab_guard() {
  local context
  if [ ! -r /etc/kubernetes/admin.conf ] && ! sudo -n test -r /etc/kubernetes/admin.conf; then
    echo "FAIL: guard: /etc/kubernetes/admin.conf is missing, so this is not the lab VM or kubeadm init did not run"
    return 1
  fi
  context=$(kube config current-context 2>/dev/null) || context=""
  if [ "$context" != "$LAB_CONTEXT" ]; then
    echo "FAIL: guard: admin.conf context is '$context', expected '$LAB_CONTEXT'"
    return 1
  fi
}

check_runtime_restarted() {
  local started state invocation
  started=$(baseline containerd-invocation)
  if [ -z "$started" ]; then
    echo "FAIL: runtime-restarted: the ConfigMap maintenance-baseline in $NAMESPACE is missing; do not delete it"
    return 1
  fi
  state=$(systemctl show containerd --property=ActiveState --value 2>/dev/null)
  invocation=$(systemctl show containerd --property=InvocationID --value 2>/dev/null)
  if [ "$state" != "active" ]; then
    echo "FAIL: runtime-restarted: the containerd service is '${state:-unknown}', expected active"
    return 1
  fi
  if [ "$invocation" = "$started" ]; then
    echo "FAIL: runtime-restarted: containerd still runs the process that started with the lab; restart the service"
    return 1
  fi
  echo "PASS: runtime-restarted: containerd is active and started again after the lab began"
}

check_probe_pods_replaced() {
  local old pods kept available
  old=$(baseline probe-uids)
  if [ -z "$old" ]; then
    echo "FAIL: probe-pods-replaced: the ConfigMap maintenance-baseline in $NAMESPACE is missing; do not delete it"
    return 1
  fi
  pods=$(kube -n "$NAMESPACE" get pods -l app=probe -o json 2>/dev/null) || pods='{"items":[]}'
  kept=$(jq -r --arg old "$old" '($old | split(" ")) as $uids
    | [.items[] | select(.metadata.uid as $uid | $uids | index($uid)) | .metadata.name] | join(", ")' <<<"$pods")
  if [ -n "$kept" ]; then
    echo "FAIL: probe-pods-replaced: drain the node so that the probe Pods are evicted and recreated; still running: $kept"
    return 1
  fi
  available=$(kube -n "$NAMESPACE" get deployment probe -o jsonpath='{.status.availableReplicas}' 2>/dev/null) || available=""
  if [ "${available:-0}" -lt 2 ]; then
    echo "FAIL: probe-pods-replaced: Deployment probe has ${available:-0} available replicas, expected 2"
    return 1
  fi
  echo "PASS: probe-pods-replaced: the probe Pods from the start are gone and two new probe Pods are available"
}

check_node_in_service() {
  local node ready unschedulable
  node=$(kube get node "$NODE" -o json 2>/dev/null) || node=""
  if [ -z "$node" ]; then
    echo "FAIL: node-in-service: node $NODE is not readable"
    return 1
  fi
  ready=$(jq -r '.status.conditions[] | select(.type=="Ready") | .status' <<<"$node")
  if [ "$ready" != "True" ]; then
    echo "FAIL: node-in-service: node $NODE is not Ready"
    return 1
  fi
  unschedulable=$(jq -r '.spec.unschedulable // false' <<<"$node")
  if [ "$unschedulable" = "true" ]; then
    echo "FAIL: node-in-service: node $NODE is still cordoned (SchedulingDisabled)"
    return 1
  fi
  echo "PASS: node-in-service: node $NODE is Ready and schedulable"
}

grade() {
  lab_guard || return 1
  case "$1" in
    runtime-restarted) check_runtime_restarted ;;
    probe-pods-replaced) check_probe_pods_replaced ;;
    node-in-service) check_node_in_service ;;
    *) echo "FAIL: Unknown outcome '$1'"; return 1 ;;
  esac
}
# <<< shared checks <<<

main() {
  grade node-in-service
}

main
